const cases = allCases();

describe('every number box is swept or excused', () => {
  it('each NumberField is swept, or listed in NOT_SWEPT with its reason', () => {
    const swept = new Set(sweptInputs().map(i => i.field));
    const all = Object.values(NumberField).filter((f): f is NumberField => f instanceof NumberField);
    const neither = all.filter(f => !swept.has(f) && !NOT_SWEPT.has(f));
    expect(neither.map(f => f.value)).toEqual([]);
  });

  it('every listed breaking case is a case the sweep runs', () => {
    const keys = new Set(cases.map(c => c.key));
    expect([...BREAKING_TODAY].filter(k => !keys.has(k))).toEqual([]);
  });
});

describe('a typed edge value leaves the engine output finite, with no throw and no slow call', () => {
  for (const c of cases) {
    if (BREAKING_TODAY.has(c.key)) {
      it.fails(`${c.key} (BUG_20261118_input-limits-sweep)`, () => {
        expect(runCase(c.input, c.trial, c.project).findings).toEqual([]);
      });
    } else {
      it(c.key, () => {
        expect(runCase(c.input, c.trial, c.project).findings).toEqual([]);
      });
    }
  }
});
